const d = $input.first()?.json || {};

let evento = 'otro';
if (d.callback_query) evento = 'callback';
else if (d.message) evento = 'message';

return [{ json: { ...d, evento } }];

const m = $json.message || {};

function txt(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function normalizeCommand(v) {
  return String(v || '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[.!?]+$/g, '')
    .replace(/\s+/g, ' ');
}

const tieneVoice = !!m.voice?.file_id;
const tieneAudio = !!m.audio?.file_id;
const tieneTexto = txt(m.text) !== '';

let tipo = 'otro';
let file_id = '';
let texto = '';

if (tieneVoice) {
  tipo = 'audio';
  file_id = txt(m.voice.file_id);
} else if (tieneAudio) {
  tipo = 'audio';
  file_id = txt(m.audio.file_id);
} else if (tieneTexto) {
  texto = txt(m.text);
  const cmd = normalizeCommand(texto);
  const esCierre = /^(cierra|cerrar|finaliza|finalizar|termina|terminar)( el| la)? (informe|valoracion)$/.test(cmd)
    || ['termine la valoracion', 'terminé la valoración', 'ya termine', 'ya terminé'].includes(texto.trim().toLowerCase());

  tipo = esCierre ? 'cerrar' : 'texto';
}

return [{
  json: {
    tipo,
    file_id,
    texto,
    telegram_chat_id: txt(m.chat?.id),
    telegram_user_id: txt(m.from?.id),
    telegram_username: txt(m.from?.username),
    telegram_nombre: [txt(m.from?.first_name), txt(m.from?.last_name)].filter(Boolean).join(' ').trim(),
    telegram_message_id: txt(m.message_id),
    telegram_fecha_unix: Number(m.date || 0),
    raw_message: m
  }
}];

const d = $input.first()?.json || {};
const raw = String(d.texto || '').trim();

function normalize(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const closeRegex = /\b(cierra|cerrar|finaliza|finalizar|finalice|termina|terminar|termine)\s+(el\s+|la\s+)?(informe|valoracion)\b/i;
const cerrar_solicitado = closeRegex.test(normalize(raw));
const limpio = raw.replace(/\b(cierra|cerrar|finaliza|finalizar|finalice|termina|terminar|termine)\s+(el\s+|la\s+)?(informe|valoraci[oó]n)\b[.!]?/ig, '').trim();

return [{
  json: {
    ...d,
    texto_valoracion: limpio || raw,
    texto_original: raw,
    transcripcion: '',
    tipo_entrada: 'texto',
    cerrar_solicitado,
    solo_cierre: cerrar_solicitado && limpio.length === 0
  }
}];

const t = $input.first()?.json || {};
const base = $('Normalizar Telegram4').first().json || {};

const transcript = String(t.text || t.transcript || t.output_text || t.output || '').trim();

function normalize(v) {
  return String(v || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const closeRegex = /\b(cierra|cerrar|finaliza|finalizar|finalice|termina|terminar|termine)\s+(el\s+|la\s+)?(informe|valoracion)\b/i;
const cerrar_solicitado = closeRegex.test(normalize(transcript));
const limpio = transcript.replace(/\b(cierra|cerrar|finaliza|finalizar|finalice|termina|terminar|termine)\s+(el\s+|la\s+)?(informe|valoraci[oó]n)\b[.!]?/ig, '').trim();

return [{
  json: {
    ...base,
    texto_valoracion: limpio || transcript,
    texto_original: '',
    transcripcion: transcript,
    tipo_entrada: 'audio',
    cerrar_solicitado,
    solo_cierre: cerrar_solicitado && limpio.length === 0
  }
}];

const agent = $input.first()?.json || {};
const base = (() => {
  try { return $('Preparar Texto4').first().json || {}; } catch (_) {}
  try { return $('Preparar Transcripción4').first().json || {}; } catch (_) {}
  return $('Normalizar Telegram4').first().json || {};
})();

function parseAny(v) {
  if (v && typeof v === 'object') return v;
  let s = String(v ?? '').trim();
  if (!s) return {};
  s = s.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try { return JSON.parse(s); } catch (_) {}
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try { return JSON.parse(s.slice(start, end + 1)); } catch (_) {}
  }
  return {};
}

const extracted = parseAny(agent.output ?? agent.text ?? agent.response ?? agent);
const telefono = String(extracted.telefono_paciente || '').replace(/\D/g, '');
const allowedUrgency = new Set(['sin_especificar', 'normal', 'prioritaria', 'urgente']);
let fecha = String(extracted.fecha_valoracion || '').trim();
if (fecha && !/^\d{4}-\d{2}-\d{2}(?:[T ][0-9:.\-+Z]+)?$/i.test(fecha)) {
  fecha = '';
}

let costoCotizado = null;
const costoRaw = extracted.costo_cotizado;
if (costoRaw !== null && costoRaw !== undefined && String(costoRaw).trim() !== '') {
  const numero = Number(String(costoRaw).replace(/\$/g, '').replace(/,/g, '').trim());
  if (Number.isFinite(numero) && numero >= 0) costoCotizado = numero;
}

const escaladoCloser =
  extracted.escalado_closer === true ||
  String(extracted.escalado_closer || '').trim().toLowerCase() === 'true';

return [{
  json: {
    nombre_paciente: String(extracted.nombre_paciente || '').trim(),
    telefono_paciente: telefono,
    fecha_valoracion: fecha,
    motivo_consulta: String(extracted.motivo_consulta || '').trim(),
    hallazgos: String(extracted.hallazgos || '').trim(),
    diagnostico: String(extracted.diagnostico || '').trim(),
    tratamiento_recomendado: String(extracted.tratamiento_recomendado || '').trim(),
    piezas_involucradas: String(extracted.piezas_involucradas || '').trim(),
    urgencia: allowedUrgency.has(String(extracted.urgencia || '')) ? String(extracted.urgencia) : 'sin_especificar',
    observaciones: String(extracted.observaciones || '').trim(),
    tipo_valoracion: String(extracted.tipo_valoracion || '').trim(),
    costo_cotizado: costoCotizado,
    promocion_aplicada: String(extracted.promocion_aplicada || '').trim(),
    objeciones: String(extracted.objeciones || '').trim(),
    escalado_closer: escaladoCloser,
    escalado_motivo: String(extracted.escalado_motivo || '').trim(),
    requiere_revision_manual: extracted.requiere_revision_manual === true || String(extracted.requiere_revision_manual || '').trim().toLowerCase() === 'true',
    razon_revision: String(extracted.razon_revision || '').trim(),
    telegram_chat_id: String(base.telegram_chat_id || ''),
    telegram_user_id: String(base.telegram_user_id || ''),
    telegram_username: String(base.telegram_username || ''),
    telegram_nombre: String(base.telegram_nombre || ''),
    telegram_message_id: String(base.telegram_message_id || ''),
    tipo_entrada: String(base.tipo_entrada || base.tipo || ''),
    texto_original: String(base.texto_original || ''),
    transcripcion: String(base.transcripcion || ''),
    texto_fuente: String(base.texto_valoracion || base.texto || ''),
    extraccion_ia: extracted,
    cerrar_solicitado: Boolean(base.cerrar_solicitado),
    solo_cierre: Boolean(base.solo_cierre)
  }
}];

