const cq = $json.callback_query || {};
const data = String(cq.data || '').trim();
const idx = data.indexOf(':');
const accion = idx >= 0 ? data.slice(0, idx) : data;
const borradorId = idx >= 0 ? data.slice(idx + 1) : '';

return [{
  json: {
    accion,
    borrador_id: borradorId,
    callback_query_id: String(cq.id || ''),
    telegram_chat_id: String(cq.message?.chat?.id || ''),
    telegram_message_id: String(cq.message?.message_id || ''),
    telegram_user_id: String(cq.from?.id || ''),
    raw_callback: cq
  }
}];

const d = $input.first()?.json || {};
const e = d.extraccion && typeof d.extraccion === 'object' ? d.extraccion : {};
return [{ json: { ...e, borrador_id: String(d.borrador_id || '') } }];

