    ? '\nSiguiente paciente: ' + $json.siguiente_nombre
    : '\nSiguiente paciente: no hay nadie en espera';
  return '✅ Informe guardado y sincronizado al CRM\n\n' +
    'Paciente: ' + ($json.nombre_paciente || 'Sin nombre') +
    '\nLead ID: ' + ($json.lead_id || 'No encontrado') +
    '\nValoración ID: ' + $json.valoracion_id +
    '\nEstado comercial: ' + ($json.estado_comercial || 'valorado') +
